#!/usr/bin/env bash
# Tutos d'administration : 5 tutos, leurs fiches dans la doc admin, leurs tests.
# Prérequis : apply-docs-tutos-membres.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-tutos-admin.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/(admin)/dashboard/page.tsx" 2>/dev/null | grep -qF "data-tour=\"dashboard.contents\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### Un nom, deux éléments" "apps/web/content/docs/dev/etude-de-cas/un-tutoriel-en-donnees.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-tutos-membres.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/index.mdx" "apps/web/src/app/(admin)/dashboard/breaking-news/page.tsx" "apps/web/src/app/(admin)/dashboard/layout.tsx" "apps/web/src/app/(admin)/dashboard/page.tsx" "apps/web/src/app/(admin)/dashboard/pages/page.tsx" "apps/web/src/app/(admin)/dashboard/tickets/[id]/page.tsx" "apps/web/src/app/(admin)/dashboard/tickets/page.tsx" "apps/web/src/app/(admin)/dashboard/users/page.tsx" "apps/web/src/features/admin/breaking-news/forms/BreakingNewsForm.tsx" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/features/tours/definitions/admin.posts.create.ts" "apps/web/src/features/tours/tour.registry.ts" "e2e/tutoriel.spec.ts")
EXPECT=("23920a801d63:apps/web/content/docs/admin/index.mdx" "4b7504cb8456:apps/web/src/app/(admin)/dashboard/breaking-news/page.tsx" "073e0498a65c:apps/web/src/app/(admin)/dashboard/layout.tsx" "b86395561740:apps/web/src/app/(admin)/dashboard/page.tsx" "056c9dafccad:apps/web/src/app/(admin)/dashboard/pages/page.tsx" "5f62d4f11485:apps/web/src/app/(admin)/dashboard/tickets/[id]/page.tsx" "0b465966bf6d:apps/web/src/app/(admin)/dashboard/tickets/page.tsx" "7eb1c9975071:apps/web/src/app/(admin)/dashboard/users/page.tsx" "94e403ec8db5:apps/web/src/features/admin/breaking-news/forms/BreakingNewsForm.tsx" "a368ad418653:apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "0710cdde7cf8:apps/web/src/features/docs/lib/docs.navigation.ts" "8b9a644c5b50:apps/web/src/features/tours/definitions/admin.posts.create.ts" "c52f87700ada:apps/web/src/features/tours/tour.registry.ts" "435e128063b6:e2e/tutoriel.spec.ts")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/admin/creer-un-post.mdx" "apps/web/content/docs/admin/creer-un-utilisateur.mdx" "apps/web/content/docs/admin/creer-une-actualite.mdx" "apps/web/content/docs/admin/pages-editoriales.mdx" "apps/web/content/docs/admin/tableau-de-bord.mdx" "apps/web/content/docs/admin/traiter-une-demande.mdx" "apps/web/src/features/tours/definitions/admin.breaking-news.create.ts" "apps/web/src/features/tours/definitions/admin.pages.publication.ts" "apps/web/src/features/tours/definitions/admin.tableau-de-bord.ts" "apps/web/src/features/tours/definitions/admin.tickets.traiter.ts" "apps/web/src/features/tours/definitions/admin.users.create.ts" "e2e/tutos-admin.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "data-tour=\"dashboard.contents\"" "apps/web/src/app/(admin)/dashboard/page.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
